@n5 syntax.nominal head="weekday"
@k1 syntax.coordination conjunction="and" conjunct=$c2 conjunct=$c3
@c3 syntax.clause form=nonfinite verb="make" modifier="bigger" complement=$n6
@n6 syntax.nominal dependent="the" head="font"

